/**
 * The source under a repository that no command `suss init` prints will
 * read, and why, so a user does not take a quiet report for a full one.
 *
 * Three kinds are found. A project deeper than init looks for projects,
 * whose dependencies match packs that would read it. Files in a format
 * no adapter reads, such as Vue single-file components. And a client
 * generated by a tool whose calls no pack reads yet, found by the line
 * the tool writes at the top of each file.
 *
 * A folder another project's read covers is left out, so the list never
 * says code is unread when it may not be. So is a deep folder whose
 * manifest matches no pack, which is usually tooling.
 */

import fs from "node:fs";
import path from "node:path";

import {
  declaredPacks,
  inspectProject,
  languageOf,
  readCommands,
} from "./init.js";
import { isSkippedDirectory } from "./language.js";
import {
  hasProjectSource,
  headOf,
  isSameOrUnder,
  PROJECT_WALK_DEPTH,
  TEST_DIRECTORIES,
} from "./projectSource.js";
import { filesBelow, isProjectIn, projectsBelow } from "./projectsBelow.js";

import type { InitTarget } from "./initTargets.js";
import type { Language } from "./language.js";

export interface UnreadSource {
  /** Relative to the directory init ran in, or "." for that directory. */
  directory: string;
  /** Why, a few words each. */
  reasons: string[];
}

/** File formats no adapter reads, and what to call them. */
const UNREAD_FORMATS: Record<string, { one: string; many: string }> = {
  ".vue": {
    one: "Vue single-file component",
    many: "Vue single-file components",
  },
  ".svelte": { one: "Svelte component", many: "Svelte components" },
};

/** Generators whose clients no pack reads, by the line they write at the top of each file. */
const UNREAD_GENERATED_CLIENTS = [
  { mark: "@hey-api/openapi-ts", tool: "@hey-api/openapi-ts" },
];

/** A generated file's first line is well inside this. */
const GENERATED_HEAD_BYTES = 256;

const MANIFEST_LANGUAGES: readonly Language[] = [
  "typescript",
  "python",
  "ruby",
];

interface Walked {
  /** Folders below the root with a manifest, relative to it. */
  projects: string[];
  /** Files in a format no adapter reads, counted by format under the nearest project folder. */
  formats: Map<string, Map<string, number>>;
  /** Folders with a generated client, and the tool that wrote it. */
  generated: Map<string, string>;
}

export async function unreadSourceUnder(
  root: string,
  targets: readonly InitTarget[],
): Promise<UnreadSource[]> {
  const walked: Walked = {
    projects: [],
    formats: new Map(),
    generated: new Map(),
  };
  walk(root, root, ".", 0, walked);

  const looked = foldersInitLooksAt(root);
  const reasons = new Map<string, string[]>();
  const add = (directory: string, reason: string): void => {
    reasons.set(directory, [...(reasons.get(directory) ?? []), reason]);
  };

  for (const directory of walked.projects.filter((one) => !looked.has(one))) {
    const packs = await packsThatWouldRead(root, directory, targets);
    if (packs.length > 0) {
      add(
        directory,
        `init does not look for projects this deep, and ${packs.join(", ")} would read it; run \`suss init ${directory}\``,
      );
    }
  }

  for (const [directory, counts] of walked.formats) {
    for (const [extension, count] of counts) {
      const name = UNREAD_FORMATS[extension];
      if (name !== undefined) {
        add(
          directory,
          `${count} ${count === 1 ? name.one : name.many}, a format suss does not read`,
        );
      }
    }
  }

  // A generator writes helper folders inside its own, and the outer one says it all.
  const generated = [...walked.generated].filter(
    ([directory]) =>
      ![...walked.generated.keys()].some(
        (other) => other !== directory && isSameOrUnder(directory, other),
      ),
  );
  for (const [directory, tool] of generated) {
    add(
      directory,
      `a client ${tool} generated; suss does not read the calls made through it`,
    );
  }

  return [...reasons]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([directory, said]) => ({ directory, reasons: said }));
}

/**
 * The packs init would run on a folder it did not look at, in each
 * language the folder has a manifest and source for that no project
 * above it reads.
 */
async function packsThatWouldRead(
  root: string,
  directory: string,
  targets: readonly InitTarget[],
): Promise<string[]> {
  const full = path.join(root, directory);
  const languages = MANIFEST_LANGUAGES.filter(
    (language) =>
      hasManifest(full, language) &&
      !isCovered(directory, language, targets) &&
      hasProjectSource(full, language),
  );
  if (languages.length === 0) {
    return [];
  }

  const report = await inspectProject(full);
  return declaredPacks(report)
    .filter(
      (suggestion) =>
        suggestion.kind !== "contract" &&
        languages.includes(languageOf(suggestion)),
    )
    .map((suggestion) => suggestion.name);
}

/**
 * A folder is covered in a language when init reports on that folder
 * itself, whose own lines say what happens to it, or when a project at
 * or above it has an extract in that language.
 */
function isCovered(
  directory: string,
  language: Language,
  targets: readonly InitTarget[],
): boolean {
  return targets.some(
    (target) =>
      target.directory === directory ||
      (isSameOrUnder(directory, target.directory) &&
        readCommands(target.report, target.directory).some(
          (command) => command.language === language && !command.effectsOnly,
        )),
  );
}

/** The files that make a folder a project of its own to init. */
const HAS_MANIFEST: Record<Language, (dir: string) => boolean> = {
  typescript: (dir) => fs.existsSync(path.join(dir, "package.json")),
  python: (dir) => isProjectIn(dir, "python"),
  ruby: (dir) => isProjectIn(dir, "ruby"),
};

const hasManifest = (dir: string, language: Language): boolean =>
  HAS_MANIFEST[language](dir);

/** The folders below the root that init inspects as projects of their own. */
function foldersInitLooksAt(root: string): Set<string> {
  return new Set(
    [
      ...filesBelow(root, ["package.json"]),
      ...projectsBelow(root, "python"),
      ...projectsBelow(root, "ruby"),
    ].map((marker) => path.dirname(marker)),
  );
}

function walk(
  root: string,
  dir: string,
  owner: string,
  depth: number,
  walked: Walked,
): void {
  if (depth > PROJECT_WALK_DEPTH) {
    return;
  }

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (
        isSkippedDirectory(entry.name) ||
        TEST_DIRECTORIES.has(entry.name) ||
        fs.existsSync(path.join(full, ".git"))
      ) {
        continue;
      }

      const relative = path.relative(root, full);
      const isProject = MANIFEST_LANGUAGES.some((language) =>
        hasManifest(full, language),
      );
      if (isProject) {
        walked.projects.push(relative);
      }
      walk(root, full, isProject ? relative : owner, depth + 1, walked);
      continue;
    }

    countFile(root, full, owner, walked);
  }
}

function countFile(
  root: string,
  file: string,
  owner: string,
  walked: Walked,
): void {
  const extension = path.extname(file);
  if (UNREAD_FORMATS[extension] !== undefined) {
    const counts = walked.formats.get(owner) ?? new Map<string, number>();
    counts.set(extension, (counts.get(extension) ?? 0) + 1);
    walked.formats.set(owner, counts);
    return;
  }

  if (!file.endsWith(".gen.ts")) {
    return;
  }
  const head = headOf(file, GENERATED_HEAD_BYTES);
  const client = UNREAD_GENERATED_CLIENTS.find((one) =>
    head.includes(one.mark),
  );
  if (client !== undefined) {
    walked.generated.set(
      path.relative(root, path.dirname(file)) || ".",
      client.tool,
    );
  }
}
